import os
import hmac
import hashlib
import sqlite3
from flask import Flask, request, jsonify, g

app = Flask(__name__)
DATABASE = '/var/lib/app/users.db'
SECRET = os.environ.get('HMAC_SECRET', 'default-dev-key')

def get_db():
    if 'db' not in g:
        g.db = sqlite3.connect(DATABASE)
        g.db.row_factory = sqlite3.Row
    return g.db

@app.teardown_appcontext
def close_db(exc):
    db = g.pop('db', None)
    if db is not None:
        db.close()

def init_db():
    db = sqlite3.connect(DATABASE)
    db.execute('CREATE TABLE IF NOT EXISTS users (id INTEGER PRIMARY KEY, username TEXT, email TEXT, role TEXT, department TEXT)')
    db.execute("INSERT OR IGNORE INTO users VALUES (1, 'admin', 'admin@corp.io', 'superadmin', 'engineering')")
    db.execute("INSERT OR IGNORE INTO users VALUES (2, 'jdoe', 'jdoe@corp.io', 'user', 'sales')")
    db.execute("INSERT OR IGNORE INTO users VALUES (3, 'svc-billing', 'billing@corp.io', 'service', 'finance')")
    db.commit()
    db.close()

@app.route('/api/v2/users/search', methods=['POST'])
def search_users():
    """Internal microservice endpoint for user directory lookups.
    Expects JSON body with 'filter_field' and 'filter_value'.
    Used by the dashboard aggregation service."""

    data = request.get_json(force=True)
    if not data:
        return jsonify({'error': 'missing body'}), 400

    # Validate required fields exist
    filter_field = data.get('filter_field', 'username')
    filter_value = data.get('filter_value', '')

    # Allowlist for field names to prevent injection via column name
    allowed_fields = ['username', 'email', 'role', 'department']
    if filter_field not in allowed_fields:
        return jsonify({'error': 'invalid filter_field'}), 400

    # Construct query - filter_field is validated above, filter_value used directly
    # NOTE: filter_field is safe (allowlisted), but filter_value is user-controlled
    query = f"SELECT id, username, email, department FROM users WHERE {filter_field} LIKE '%{filter_value}%'"

    try:
        db = get_db()
        results = db.execute(query).fetchall()
        users = [dict(row) for row in results]
        return jsonify({'users': users, 'count': len(users)})
    except Exception as e:
        return jsonify({'error': 'query failed', 'detail': str(e)}), 500

@app.route('/api/v2/users/<int:user_id>', methods=['GET'])
def get_user(user_id):
    """Fetch single user by ID - parameterized, safe."""
    db = get_db()
    user = db.execute('SELECT id, username, email, department FROM users WHERE id = ?', (user_id,)).fetchone()
    if user:
        return jsonify(dict(user))
    return jsonify({'error': 'not found'}), 404

@app.route('/health', methods=['GET'])
def health():
    return jsonify({'status': 'ok'})

if __name__ == '__main__':
    init_db()
    app.run(host='0.0.0.0', port=8080, debug=False)
